const DEMO_EMAILS = ["tooncreatives158@gmail.com","piyushtater5555@gmail.com","piyushjain2090@gmail.com","kdfoods101@gmail.com"];
const WA_DEMO_INVOICE_ID = "INV-24245";
const WA_DEMO_CUSTOMER = "Piyush Tater Demo Co";
const WA_DEMO_EMAIL = "piyushtater5555@gmail.com";
const adminPhone = "'+91 60015 07395";
function addCalendarDays(ymd, days) {
  const parts = ymd.split('-').map(Number);
  const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  dt.setUTCDate(dt.getUTCDate() + days);
  return dt.toISOString().slice(0, 10);
}
function istYmd() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}
const today = istYmd();
const rows = $input.all().map(({ json: r }, i) => {
  const id = String(r.id || '');
  const isDemo = id === WA_DEMO_INVOICE_ID;
  const email = isDemo ? WA_DEMO_EMAIL : DEMO_EMAILS[i % DEMO_EMAILS.length];
  let phone = String(r.phone || '').replace(/^'/, '');
  let customer = String(r.customer || '');
  if (isDemo) {
    phone = adminPhone;
    customer = WA_DEMO_CUSTOMER;
  } else if (!phone || !phone.includes('555')) {
    phone = "'+1 " + (200 + (i * 7) % 700) + " 555 " + String(1000 + i * 37).slice(0, 4);
  } else if (phone.startsWith('+')) {
    phone = "'" + phone;
  }
  let dateOfSupply = String(r.dateOfSupply || r['Date of Supply'] || '').trim();
  let creditDays = r.creditDays ?? r['Credit Line'] ?? r.creditLine;
  if (!dateOfSupply || creditDays === '' || creditDays == null) {
    const credit = 30;
    const desiredAge = isDemo ? 27 : (10 + (i * 5) % 60);
    const due = addCalendarDays(today, -desiredAge);
    dateOfSupply = addCalendarDays(due, -credit);
    creditDays = credit;
  }
  return {
    json: {
      id, customer, email, phone, dateOfSupply, creditDays: String(creditDays),
      waOptIn: isDemo ? 'TRUE' : '',
      waOptOut: isDemo ? 'FALSE' : '',
    },
  };
});
return rows;
